describe('Optimistic UI Updates on Like Post', () => {
  beforeEach(() => {
    cy.visit('/posts');
  });

  it('should display optimistic like count and update on successful API call', () => {
    // Get a post to like
    cy.get('[data-testid="post-card-1"]').should('be.visible');
    cy.get('[data-testid="like-button-1"]').click();

    // Verify optimistic UI is displayed
    cy.get('[data-testid="like-count-1"]').should('contain', '1');
    cy.get('[data-testid="like-icon-1"]').should('contain', '👍');

    // Wait for API call
    cy.intercept('POST', '/api/posts/1/like').as('likePost');
    cy.wait('@likePost');

    // Verify API call was successful
    cy.get('[data-testid="like-count-1"]').should('contain', '2');
    cy.get('[data-testid="like-icon-1"]').should('contain', '👍');

    // Verify like button is disabled after first click
    cy.get('[data-testid="like-button-1"]').should('be.disabled');
  });

  it('should revert optimistic UI if API call fails', () => {
    // Get a post to like
    cy.get('[data-testid="post-card-2"]').should('be.visible');
    cy.get('[data-testid="like-button-2"]').click();

    // Verify optimistic UI is displayed
    cy.get('[data-testid="like-count-2"]').should('contain', '1');
    cy.get('[data-testid="like-icon-2"]').should('contain', '👍');

    // Simulate API failure
    cy.intercept('POST', '/api/posts/2/like', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('likePostFail');

    // Wait for failed API call
    cy.wait('@likePostFail');

    // Verify optimistic UI is reverted
    cy.get('[data-testid="like-count-2"]').should('contain', '0');
    cy.get('[data-testid="like-icon-2"]').should('contain', '👎');

    // Verify like button is enabled again
    cy.get('[data-testid="like-button-2"]').should('not.be.disabled');
  });
});
